// A mock plc.directory that can actually answer a DID lookup.
//
// tools/mcp's stub answers every path with `{}`, which is all its suite needs: the PDS POSTs
// a genesis operation during account creation and never reads anything back. A real OAuth
// *client* is different — it resolves the `sub` DID it was handed, finds that DID's PDS, and
// checks the token really came from there. That is the whole point of the check (it stops a
// hostile authorization server minting tokens for someone else's account), so a client that
// performs it correctly cannot be tested against a directory that returns `{}`.
//
// This is a local variant rather than a change to the shared harness: two other suites depend
// on that module, and neither needs a stateful directory.
//
// The documents served here are not synthesized. The harness reads each one back from the PDS
// (`com.atproto.repo.describeRepo` returns `didDoc`) and registers it, so a client resolving a
// DID sees the same document the server would have published to the real directory.

import * as http from 'node:http';

export interface MockPlc {
  url: string;
  /** Publish a DID document, making `GET /{did}` resolvable. */
  register: (did: string, document: unknown) => void;
  close: () => void;
}

export function startMockPlc(): Promise<MockPlc> {
  const documents = new Map<string, unknown>();

  return new Promise((resolve) => {
    const server = http.createServer((req, res) => {
      const path = decodeURIComponent((req.url ?? '/').split('?')[0] ?? '/');
      const did = path.slice(1);
      const document = documents.get(did);

      if (req.method === 'GET' && document) {
        res.writeHead(200, { 'content-type': 'application/json' });
        res.end(JSON.stringify(document));
        return;
      }
      if (req.method === 'GET' && did.startsWith('did:')) {
        // An unregistered DID genuinely does not exist as far as this directory is concerned;
        // 404 is what the real one returns, and answering `{}` would turn a wiring mistake
        // into a confusing parse error inside the client instead.
        res.writeHead(404, { 'content-type': 'application/json' });
        res.end(JSON.stringify({ message: 'DID not registered in the mock directory' }));
        return;
      }
      // Everything else — notably the genesis-operation POST the PDS makes during account
      // creation — keeps the stub's accept-everything behaviour.
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end('{}');
    });

    server.listen(0, '127.0.0.1', () => {
      const address = server.address() as { port: number };
      resolve({
        url: `http://127.0.0.1:${address.port}`,
        register: (did, document) => documents.set(did, document),
        close: () => {
          // Idle keep-alive sockets would otherwise keep the test process alive.
          server.closeAllConnections();
          server.close();
        },
      });
    });
  });
}

// pattern: Imperative Shell

//! The wallet-confirmed (passwordless) half of OAuth consent. Four endpoints, all keyed off the
//! single-use `pending_oauth_authorizations` row the consent page
//! (`oauth_authorize::get_authorization`) created:
//!
//! - `GET /oauth/authorize/consent-request` — wallet preview: client/origin/scope for a
//!   `user_code`, plus `matchRequired` when a push was dispatched
//! - `GET /oauth/authorize/status` — browser poll (`slow_down`-throttled), returns `{status}`
//! - `POST /oauth/authorize/approve` — device-key-signed approve/deny of a request
//! - `POST /oauth/authorize/complete` — browser exchanges an approved request for the code
//!
//! Approval is proven with a canonical device-key envelope in the `sovereign_session` mold
//! (`crypto::encode_oauth_consent_envelope`), verified against the account's **authoritative**
//! current signing authority (`identity::authority` — a did:plc rotation set, or a self-hosted
//! did:web's `#device` key), never the cached DID doc. The envelope binds `request_id`,
//! `client_id`, the decision, and a hash of the granted scope set, so an approval cannot be
//! replayed onto a different request, flipped from a denial, or widened. Replay of the same
//! envelope onto its own request is stopped by the single-use guarded status transition (the
//! `request_id` binding + single-use row together subsume a nonce store).
//!
//! **Push-to-approve (Phase C).** When the consent page dispatched a `login-approval` push for
//! the request (`pending.match_code` set), an approval must additionally present the two-digit
//! number the sign-in page displays — the mandatory anti-MFA-fatigue proof that the approver can
//! see the login surface. It is checked server-side, outside the envelope, after the signature
//! and authority checks; a mismatch is a 403 that leaves the request pending, and a denial never
//! requires it.
//!
//! Redirects read `response_mode` back off the pending row (`auth/oauth_response_mode.rs`) so
//! every answer arrives in the mode the client requested. This module never imports another
//! route handler.

use std::time::{Duration, Instant};

use axum::{
    extract::{Form, Query, State},
    http::StatusCode,
    response::{IntoResponse, Json, Response},
};
use common::{ApiError, ErrorCode, SOVEREIGN_TIMESTAMP_WINDOW_SECS};
use serde::{Deserialize, Serialize};

use crate::app::AppState;
use crate::auth::signed_proof::{decode_canonical_base64url, NONCE_BYTES, SIGNATURE_BYTES};
use crate::auth::token::generate_token;
use crate::db::oauth::store_authorization_code;
use crate::db::pending_oauth_authorizations::{
    approve_pending_authorization, complete_pending_authorization, deny_pending_authorization,
    get_pending_by_request_id, get_pending_by_user_code, insert_oauth_consent_audit_event,
    OAuthConsentAuditEventType,
};
use crate::identity::authority::{authorized_signing_keys, AuthorityError, AuthoritySet};
use crate::identity::resolution::resolve_handle_to_did;
use crate::routes::oauth_templates::{build_code_redirect, error_page};

/// Minimum spacing between accepted status polls for one request; a faster poll gets the
/// `slow_down` 429 the page's JS backs off on (the `claim_polling` discipline).
const STATUS_POLL_MIN_INTERVAL: Duration = Duration::from_secs(2);

// ── Shared helpers ──────────────────────────────────────────────────────────────

/// A request that is no longer approvable — absent, terminal, or lapsed — maps to one uniform
/// response so the caller can't probe request state beyond "pending or not".
fn not_approvable() -> ApiError {
    ApiError::new(
        ErrorCode::NotFound,
        "authorization request not found or expired",
    )
}

/// Signature / authority / binding failures share one message so the surface reveals nothing about
/// which check failed.
fn approval_rejected() -> ApiError {
    ApiError::new(
        ErrorCode::AuthenticationRequired,
        "consent approval rejected",
    )
}

/// A push-delivered request was approved without the number displayed on the login surface.
/// Deliberately distinct (403) from `approval_rejected` (401): this check runs only after the
/// envelope verified against the account's authoritative keys, so the caller is the genuine
/// wallet and telling it "wrong number, ask the user to re-read the page" is not an oracle —
/// while the request stays pending so the user can retype.
fn match_code_rejected() -> ApiError {
    ApiError::new(ErrorCode::Forbidden, "sign-in number mismatch")
}

/// Reduce the wallet's requested granted-scope string to the tokens actually on offer: `atproto` is
/// always granted (never optional), and every other token is kept only if it was part of the
/// request's snapshotted `requested_scope`. This mirrors `oauth_authorize`'s reduction filter, so a
/// tampered/injected token that was never requested cannot add scope — only narrow it.
fn reduce_granted_scope(requested_scope: &str, wallet_granted: &str) -> String {
    let wallet: Vec<&str> = wallet_granted.split_whitespace().collect();
    requested_scope
        .split_whitespace()
        .filter(|t| *t == "atproto" || wallet.contains(t))
        .collect::<Vec<_>>()
        .join(" ")
}

// ── Preview ─────────────────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct ConsentRequestQuery {
    /// Typed path: the human-entered `user_code`. Exactly one of `user_code` / `request_id`.
    user_code: Option<String>,
    /// Handoff path: the `request_id` carried by the "Open in Obsign" link.
    request_id: Option<String>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ConsentRequestPreview {
    request_id: String,
    client_id: String,
    client_name: Option<String>,
    redirect_uri: String,
    origin: Option<String>,
    ip: Option<String>,
    requested_scope: Vec<String>,
    login_hint: Option<String>,
    /// Whether approval requires the two-digit number displayed on the sign-in page (true iff a
    /// `login-approval` push was dispatched for this request — the mandatory anti-MFA-fatigue
    /// mitigation on the wallet-notified channel). The number itself is never in this response:
    /// it is the proof the approver can see the login surface.
    match_required: bool,
}

/// `GET /oauth/authorize/consent-request` — the wallet's preview of a pending request, resolved by
/// `user_code` (typed) or `request_id` (handoff). Returns 404 for anything not currently pending so
/// a guessed code reveals nothing.
pub async fn get_consent_request(
    State(state): State<AppState>,
    Query(query): Query<ConsentRequestQuery>,
) -> Result<Json<ConsentRequestPreview>, ApiError> {
    let pending = match (&query.user_code, &query.request_id) {
        (Some(code), None) => get_pending_by_user_code(&state.db, code).await?,
        (None, Some(request_id)) => get_pending_by_request_id(&state.db, request_id).await?,
        _ => {
            return Err(ApiError::new(
                ErrorCode::InvalidRequest,
                "exactly one of userCode or requestId is required",
            ))
        }
    };
    let pending = pending.filter(|p| p.status == "pending" && !p.is_expired);
    let Some(p) = pending else {
        return Err(not_approvable());
    };
    Ok(Json(ConsentRequestPreview {
        request_id: p.request_id,
        client_id: p.client_id,
        client_name: p.client_name,
        redirect_uri: p.redirect_uri,
        origin: p.origin,
        ip: p.ip,
        requested_scope: p
            .requested_scope
            .split_whitespace()
            .map(str::to_string)
            .collect(),
        login_hint: p.login_hint,
        match_required: p.match_code.is_some(),
    }))
}

// ── Status poll ─────────────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct StatusQuery {
    request_id: String,
}

#[derive(Serialize)]
struct StatusResponse {
    status: &'static str,
}

/// `GET /oauth/authorize/status?request_id=…` — the consent page's poll. Throttled per request with
/// the `slow_down` discipline (429 when polled faster than `STATUS_POLL_MIN_INTERVAL`), and reports
/// a derived `expired` for a lapsed or reclaimed request so the page stops.
pub async fn get_authorization_status(
    State(state): State<AppState>,
    Query(query): Query<StatusQuery>,
) -> Response {
    // slow_down throttle, reusing the shared poll tracker with a namespaced key so it can't collide
    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
    {
        let key = format!("consent:{}", query.request_id);
        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(last) = tracker.get(&key) {
            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
                return (
                    StatusCode::TOO_MANY_REQUESTS,
                    Json(StatusResponse {
                        status: "slow_down",
                    }),
                )
                    .into_response();
            }
        }
        tracker.insert(key, Instant::now());
    }

    let pending = match get_pending_by_request_id(&state.db, &query.request_id).await {
        Ok(p) => p,
        Err(e) => return e.into_response(),
    };
    let status = match pending {
        // Absent (never created or reclaimed) reads as expired so the page stops polling.
        None => "expired",
        Some(p) if p.status == "pending" && p.is_expired => "expired",
        Some(p) => match p.status.as_str() {
            "pending" => "pending",
            "approved" => "approved",
            "denied" => "denied",
            "completed" => "completed",
            _ => "expired",
        },
    };
    Json(StatusResponse { status }).into_response()
}

// ── Approve / deny ──────────────────────────────────────────────────────────────

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ApprovalRequest {
    did: String,
    signing_key: String,
    request_id: String,
    /// `"approve"` or `"deny"` — bound into the signed envelope so a captured denial cannot be
    /// replayed as an approval.
    decision: String,
    /// Space-joined granted-scope string the wallet chose (empty for a denial). Signed verbatim.
    #[serde(default)]
    granted_scope: String,
    /// The two-digit number the user read off the sign-in page. Required to approve a request
    /// for which a `login-approval` push was dispatched; ignored otherwise. Deliberately outside
    /// the signed envelope — it is a liveness/visibility proof checked server-side against the
    /// stored code (like the `login_hint` binding), not a statement the key needs to attest.
    #[serde(default)]
    match_code: Option<String>,
    timestamp: i64,
    nonce: String,
    signature: String,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ApprovalResponse {
    status: &'static str,
    did: String,
}

/// Whether a client-supplied `login_hint` denotes the approving account.
///
/// The hint is whatever the client forwarded from the user and is entirely unverified. An atproto
/// client sends the handle the user typed far more often than a DID, so this is deliberately not a
/// string comparison against `did` — that comparison rejected every honest sign-in whose client
/// passed a handle.
///
/// A handle binds only when **both** halves of the atproto bidirectional rule hold: the account's
/// authoritative state asserts it in `alsoKnownAs`, and the handle resolves back to this DID.
/// Assertion alone is the account's own claim — `alsoKnownAs` is writable by whoever controls the
/// DID, so any account could otherwise claim any handle and approve a request named for someone
/// else. `authority` carries that assertion read from the same authoritative source as the signing
/// keys, never the `did_documents` cache (which a Custos-hosted did:web account can rewrite under
/// session auth).
///
/// A hint that does not denote this account is `Ok(false)`, including a structurally invalid one —
/// `Err` stays reserved for a lookup the server could not complete at all, so an internal failure
/// keeps its own status instead of reading as a rejected approval. Note that a DNS/well-known
/// outage resolves to `Ok(None)` rather than an error, so a user-domain handle is refused while its
/// resolution is down; entering the DID still binds, since that path performs no resolution.
async fn hint_binds_account(
    state: &AppState,
    hint: &str,
    did: &str,
    authority: &AuthoritySet,
) -> Result<bool, ApiError> {
    if hint.starts_with("did:") {
        return Ok(hint == did);
    }

    let handle = hint.strip_prefix("at://").unwrap_or(hint);
    let handle = handle
        .strip_prefix('@')
        .unwrap_or(handle)
        .to_ascii_lowercase();

    if crate::identity::handle::validate_handle_structure(&handle).is_err() {
        return Ok(false);
    }
    if !authority.asserts_handle(&handle) {
        return Ok(false);
    }
    Ok(resolve_handle_to_did(state, &handle).await?.as_deref() == Some(did))
}

/// `POST /oauth/authorize/approve` — verify a device-key-signed approve/deny envelope against the
/// account's authoritative current signing authority and terminate the request accordingly.
pub async fn post_authorization_approve(
    State(state): State<AppState>,
    Json(request): Json<ApprovalRequest>,
) -> Result<Json<ApprovalResponse>, ApiError> {
    // 1. Cheap syntactic gates before any DB or network work.
    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
        .ok_or_else(approval_rejected)?;
    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
        return Err(approval_rejected());
    }
    let approve = match request.decision.as_str() {
        crypto::OAUTH_CONSENT_DECISION_APPROVE => true,
        crypto::OAUTH_CONSENT_DECISION_DENY => false,
        _ => return Err(approval_rejected()),
    };
    let now = crate::time::unix_now_secs();
    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
        return Err(approval_rejected());
    }

    // 2. Load the pending request; it must be currently approvable.
    let pending = get_pending_by_request_id(&state.db, &request.request_id)
        .await?
        .filter(|p| p.status == "pending" && !p.is_expired)
        .ok_or_else(not_approvable)?;

    // 3. The approving DID must be a local active account so the authorization code can be issued
    //    against it. Any `login_hint` binding is deferred to step 6, which needs the authoritative
    //    state step 5 fetches.
    if !crate::db::accounts::active_local_account_exists(&state.db, &request.did).await? {
        return Err(approval_rejected());
    }

    // 4. The granted scope the wallet signed over is the verbatim `granted_scope` string (empty for
    //    a denial); the stored set is that, reduced to what was actually requested.
    let signed_scope = if approve {
        request.granted_scope.as_str()
    } else {
        ""
    };
    let stored_scope = reduce_granted_scope(&pending.requested_scope, signed_scope);

    // 5. Verify the envelope signature, then confirm the signing key is in the account's
    //    authoritative current signing authority (never the cached DID doc). Signature first, so an
    //    invalid signature never triggers the outbound authority lookup.
    let server_did = state.config.resolve_server_did();
    let envelope = crypto::encode_oauth_consent_envelope(
        &server_did,
        &request.did,
        &request.signing_key,
        &request.request_id,
        &pending.client_id,
        &request.decision,
        signed_scope,
        request.timestamp,
        &request.nonce,
    );
    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
    crypto::verify_did_key_signature(&signing_key, &envelope, &signature)
        .map_err(|_| approval_rejected())?;

    let authority = authorized_signing_keys(&state, &request.did)
        .await
        .map_err(|error| match error {
            AuthorityError::Unauthorized(_) => approval_rejected(),
            AuthorityError::Lookup(err) => err,
        })?;
    if !authority.authorizes(&request.signing_key) {
        return Err(approval_rejected());
    }

    // 6. Account binding: a `login_hint` pre-names the account the client expects to approve, so an
    //    approval by anyone else is refused. It is bound here rather than up front because the hint
    //    is usually a handle, and resolving one belongs against the same authoritative state step 5
    //    just read — and sitting behind `authorizes` means only a genuine key holder can drive the
    //    outbound handle resolution it may perform.
    if let Some(hint) = pending.login_hint.as_deref() {
        if !hint_binds_account(&state, hint, &request.did, &authority).await? {
            return Err(approval_rejected());
        }
    }

    // 6b. Number matching (Phase C): once a `login-approval` push was dispatched for this
    //    request, an APPROVAL must present the number displayed on the sign-in page — the
    //    mandatory anti-MFA-fatigue proof that the approver can see the login surface. A wrong
    //    number is rejected WITHOUT terminating the request (the user re-reads and retypes; the
    //    approve route's per-IP rate limit bounds guessing). A denial deliberately skips the
    //    check: declining must never be harder than approving, and the recipient of an
    //    unsolicited prompt is exactly who should be able to kill it.
    if approve {
        if let Some(expected) = pending.match_code.as_deref() {
            if request.match_code.as_deref() != Some(expected) {
                return Err(match_code_rejected());
            }
        }
    }

    // 7. Terminate the request and audit it in one transaction. The guarded UPDATE is the single-use
    //    point: a replayed envelope lands on an already-terminal row and wins nothing.
    let mut tx = state.db.begin().await.map_err(|e| {
        tracing::error!(error = %e, "failed to begin consent approval transaction");
        ApiError::new(ErrorCode::InternalError, "failed to record decision")
    })?;
    let won = if approve {
        approve_pending_authorization(&mut *tx, &request.request_id, &request.did, &stored_scope)
            .await?
    } else {
        deny_pending_authorization(&mut *tx, &request.request_id, &request.did).await?
    };
    if !won {
        return Err(ApiError::new(
            ErrorCode::InvalidRequest,
            "authorization request already resolved",
        ));
    }
    let (event, detail) = if approve {
        (
            OAuthConsentAuditEventType::Approved,
            serde_json::json!({ "granted_scope": stored_scope }).to_string(),
        )
    } else {
        (
            OAuthConsentAuditEventType::Denied,
            serde_json::json!({}).to_string(),
        )
    };
    insert_oauth_consent_audit_event(
        &mut *tx,
        &uuid::Uuid::new_v4().to_string(),
        &request.request_id,
        Some(&request.did),
        &pending.client_id,
        event,
        Some(&detail),
    )
    .await?;
    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "failed to commit consent approval transaction");
        ApiError::new(ErrorCode::InternalError, "failed to record decision")
    })?;

    tracing::info!(
        account_did = %request.did,
        client_id = %pending.client_id,
        decision = %request.decision,
        authority = %authority.source,
        "wallet-confirmed OAuth consent decision recorded"
    );
    Ok(Json(ApprovalResponse {
        status: if approve { "approved" } else { "denied" },
        did: request.did,
    }))
}

// ── Complete ────────────────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct CompleteForm {
    request_id: String,
}

/// `POST /oauth/authorize/complete` — the browser exchanges an approved request for an
/// authorization code and is redirected back to the client. The guarded `approved → completed`
/// transition mints at most one code; a no-JS "I've approved — continue" button and the page's JS
/// poller both post here.
pub async fn post_authorization_complete(
    State(state): State<AppState>,
    Form(form): Form<CompleteForm>,
) -> Response {
    let issuer = state.config.public_url.trim_end_matches('/').to_string();

    // The guarded transition, authorization-code insert, and completion audit share one transaction:
    // a failed code insert rolls the `approved → completed` transition back, so the request stays
    // retryable instead of being consumed with no code ever issued.
    let token = generate_token();
    let mut tx = match state.db.begin().await {
        Ok(tx) => tx,
        Err(e) => {
            tracing::error!(error = %e, "failed to begin consent completion transaction");
            return error_page(
                "Server Error",
                "Failed to issue the authorization code. Please try again.",
            )
            .into_response();
        }
    };

    let completed = match complete_pending_authorization(&mut *tx, &form.request_id).await {
        Ok(Some(c)) => c,
        Ok(None) => {
            // Not in `approved` state: still pending, denied, expired, or already completed.
            return error_page(
                "Not Ready",
                "This authorization request has not been approved yet, or has already been used. \
                 Return to the app and start again if needed.",
            )
            .into_response();
        }
        Err(e) => return e.into_response(),
    };

    if let Err(e) = store_authorization_code(
        &mut *tx,
        &token.hash,
        &completed.client_id,
        &completed.account_did,
        &completed.code_challenge,
        &completed.code_challenge_method,
        &completed.redirect_uri,
        &completed.granted_scope,
        completed.dpop_jkt.as_deref(),
    )
    .await
    {
        tracing::error!(error = %e, "failed to store authorization code for wallet consent");
        return error_page(
            "Server Error",
            "Failed to issue the authorization code. Please try again.",
        )
        .into_response();
    }

    if let Err(e) = insert_oauth_consent_audit_event(
        &mut *tx,
        &uuid::Uuid::new_v4().to_string(),
        &form.request_id,
        Some(&completed.account_did),
        &completed.client_id,
        OAuthConsentAuditEventType::Completed,
        Some(&serde_json::json!({ "granted_scope": completed.granted_scope }).to_string()),
    )
    .await
    {
        return e.into_response();
    }

    if let Err(e) = tx.commit().await {
        tracing::error!(error = %e, "failed to commit consent completion transaction");
        return error_page(
            "Server Error",
            "Failed to issue the authorization code. Please try again.",
        )
        .into_response();
    }

    // Answer in the response mode the client asked for at PAR/authorize time (carried on
    // the pending row) — a fragment-mode browser client only ever reads `location.hash`.
    // The stored value was validated before it was written, so an unparseable one means
    // row tampering/drift; falling back to `query` (the protocol default) is the honest
    // degraded answer rather than a hard failure after consent already happened.
    let mode =
        crate::auth::oauth_response_mode::ResponseMode::parse(Some(&completed.response_mode))
            .unwrap_or(crate::auth::oauth_response_mode::ResponseMode::Query);
    build_code_redirect(
        &completed.redirect_uri,
        &token.plaintext,
        &completed.state,
        &issuer,
        mode,
    )
    .into_response()
}

