    // Status polling faster than the minimum interval is throttled (the slow_down discipline).
    #[tokio::test]
    async fn status_polling_is_throttled() {
        let plc = MockServer::start().await;
        let state = setup(&plc).await;
        let request_id = "poauth_poll";
        seed_pending(&state, request_id, None).await;
        let uri = format!("/oauth/authorize/status?request_id={request_id}");

        let first = get(state.clone(), &uri).await;
        assert_eq!(first.status(), StatusCode::OK);
        let second = get(state.clone(), &uri).await;
        assert_eq!(second.status(), StatusCode::TOO_MANY_REQUESTS);
    }

    // An expired pending request is not approvable and reports expired.
    #[tokio::test]
    async fn expired_request_is_not_approvable() {
        let plc = MockServer::start().await;
        let state = setup(&plc).await;
        let key = p256_key();
        mount_audit_log(&plc, &[&key.did]).await;
        let request_id = "poauth_expired";
        // Insert already-expired (negative TTL).
        let new = NewPendingOAuthAuthorization {
            request_id,
            user_code: "EXPI-RED0",
            client_id: CLIENT_ID,
            client_name: Some("Test App"),
            redirect_uri: REDIRECT_URI,
            code_challenge: "e3b0c44298fc1c149afb",
            code_challenge_method: "S256",
            state: "teststate",
            response_type: "code",
            response_mode: "query",
            requested_scope: REQUESTED_SCOPE,
            login_hint: None,
            origin: None,
            ip: None,
            user_agent: None,
            dpop_jkt: None,
            ttl_secs: -10,
        };
        crate::db::pending_oauth_authorizations::insert_pending_authorization(&state.db, &new)
            .await
            .unwrap();

        let status = body_json(
            get(
                state.clone(),
                &format!("/oauth/authorize/status?request_id={request_id}"),
            )
            .await,
        )
        .await;
        assert_eq!(status["status"], "expired");

        let resp = post_json(
            state.clone(),
            "/oauth/authorize/approve",
            approval_body(
                &state,
                &key,
                request_id,
                "approve",
                REQUESTED_SCOPE,
                now(),
                7,
            ),
        )
        .await;
        assert_eq!(resp.status(), StatusCode::NOT_FOUND);
    }

    /// Once a `login-approval` push was dispatched, approval REQUIRES the number displayed on
    /// the sign-in page: a missing or wrong number is a 403 that leaves the request pending
    /// (the user re-reads and retypes), and the correct number approves. The AC verbatim:
    /// "approval requires the matching number + biometric; a wrong number cannot approve."
    #[tokio::test]
    async fn push_delivered_request_requires_the_matching_number() {
        let plc = MockServer::start().await;
        let state = setup(&plc).await;
        let key = p256_key();
        mount_audit_log(&plc, &[&key.did]).await;
        let request_id = "poauth_push";
        seed_pending(&state, request_id, None).await;
        assert!(
            crate::db::pending_oauth_authorizations::set_push_dispatched(
                &state.db, request_id, "42"
            )
            .await
            .unwrap()
        );

        // The wallet preview announces the requirement (never the number itself).
        let preview = body_json(
            get(
                state.clone(),
                "/oauth/authorize/consent-request?user_code=TEST-CODE",
            )
            .await,
        )
        .await;
        assert_eq!(preview["matchRequired"], true);
        assert!(
            preview.get("matchCode").is_none(),
            "the number must never reach the wallet in the preview"
        );

        // No number → 403, request still pending.
        let resp = post_json(
            state.clone(),
            "/oauth/authorize/approve",
            approval_body(
                &state,
                &key,
                request_id,
                "approve",
                REQUESTED_SCOPE,
                now(),
                31,
            ),
        )
        .await;
        assert_eq!(resp.status(), StatusCode::FORBIDDEN);

        // Wrong number → 403, request still pending.
        let mut wrong = approval_body(
            &state,
            &key,
            request_id,
            "approve",
            REQUESTED_SCOPE,
            now(),
            32,
        );
        wrong["matchCode"] = json!("24");
        let resp = post_json(state.clone(), "/oauth/authorize/approve", wrong).await;
        assert_eq!(resp.status(), StatusCode::FORBIDDEN);
        let status = body_json(
            get(
                state.clone(),
                &format!("/oauth/authorize/status?request_id={request_id}"),
            )
            .await,
        )
        .await;
        assert_eq!(
            status["status"], "pending",
            "a wrong number must not terminate the request"
        );

        // The matching number approves.
        let mut right = approval_body(
            &state,
            &key,
            request_id,
            "approve",
            REQUESTED_SCOPE,
            now(),
            33,
        );
        right["matchCode"] = json!("42");
        let resp = post_json(state.clone(), "/oauth/authorize/approve", right).await;
        assert_eq!(resp.status(), StatusCode::OK);
        let body = body_json(resp).await;
        assert_eq!(body["status"], "approved");
    }

    /// Denying never requires the number: declining must not be harder than approving, and the
    /// recipient of an unsolicited push is exactly who should be able to kill the request.
    #[tokio::test]
    async fn denial_does_not_require_the_match_number() {
        let plc = MockServer::start().await;
        let state = setup(&plc).await;
        let key = p256_key();
        mount_audit_log(&plc, &[&key.did]).await;
        let request_id = "poauth_push_deny";
        seed_pending(&state, request_id, None).await;
        assert!(
            crate::db::pending_oauth_authorizations::set_push_dispatched(
                &state.db, request_id, "17"
            )
            .await
            .unwrap()
        );

        let resp = post_json(
            state.clone(),
            "/oauth/authorize/approve",
            approval_body(&state, &key, request_id, "deny", "", now(), 34),
        )
        .await;
        assert_eq!(resp.status(), StatusCode::OK);
        let body = body_json(resp).await;
        assert_eq!(body["status"], "denied");
    }

    /// The dispatch latch is single-use and pending-only: a second dispatch cannot rotate the
    /// number out from under the page, and a resolved request cannot have a requirement
    /// retrofitted onto it.
    #[tokio::test]
    async fn push_dispatch_latches_exactly_once() {
        let plc = MockServer::start().await;
        let state = setup(&plc).await;
        let request_id = "poauth_latch";
        seed_pending(&state, request_id, None).await;
        let db = &state.db;
        assert!(
            crate::db::pending_oauth_authorizations::set_push_dispatched(db, request_id, "10")
                .await
                .unwrap()
        );
        assert!(
            !crate::db::pending_oauth_authorizations::set_push_dispatched(db, request_id, "99")
                .await
                .unwrap(),
            "a second dispatch must not overwrite the displayed number"
        );
        let row =
            crate::db::pending_oauth_authorizations::get_pending_by_request_id(db, request_id)
                .await
                .unwrap()
                .unwrap();
        assert_eq!(row.match_code.as_deref(), Some("10"));
    }

    /// The completion redirect must answer in the response mode the client asked for at
    /// PAR/authorize time (carried on the pending row) — a fragment-mode browser client
    /// only ever reads `location.hash`.
    #[tokio::test]
    async fn completion_answers_in_the_stored_fragment_response_mode() {
        let state = crate::app::test_state().await;
        register_oauth_client(&state.db, CLIENT_ID, CLIENT_METADATA)
            .await
            .unwrap();
        sqlx::query(
            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
             VALUES (?, 'owner@example.com', NULL, datetime('now'), datetime('now'))",
        )
        .bind(DID)
        .execute(&state.db)
        .await
        .unwrap();

        let request_id = "poauth_fragment_mode";
        let new = crate::db::pending_oauth_authorizations::NewPendingOAuthAuthorization {
            request_id,
            user_code: "FRAG-MODE",
            client_id: CLIENT_ID,
            client_name: Some("Test App"),
            redirect_uri: REDIRECT_URI,
            code_challenge: "e3b0c44298fc1c149afb",
            code_challenge_method: "S256",
            state: "teststate",
            response_type: "code",
            response_mode: "fragment",
            requested_scope: REQUESTED_SCOPE,
            login_hint: None,
            origin: None,
            ip: None,
            user_agent: None,
            dpop_jkt: None,
            ttl_secs: 300,
        };
        crate::db::pending_oauth_authorizations::insert_pending_authorization(&state.db, &new)
            .await
            .unwrap();
        // Flip straight to approved (the wallet-approval leg is covered by its own tests).
        sqlx::query(
            "UPDATE pending_oauth_authorizations \
             SET status = 'approved', account_did = ?, granted_scope = 'atproto' \
             WHERE request_id = ?",
        )
        .bind(DID)
        .bind(request_id)
        .execute(&state.db)
        .await
        .unwrap();

        let resp = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/oauth/authorize/complete")
                    .header("content-type", "application/x-www-form-urlencoded")
                    .body(Body::from(format!("request_id={request_id}")))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(resp.status(), StatusCode::SEE_OTHER);
        let location = resp.headers().get("location").unwrap().to_str().unwrap();
        assert!(
            location.starts_with(&format!("{REDIRECT_URI}#code=")),
            "fragment mode must deliver the code in the URL fragment: {location}"
        );
        assert!(
            !location.contains('?'),
            "no query-string delivery in fragment mode: {location}"
        );
    }
}

