231	        let doc = document(json!([{
232	            "id": format!("{WEB_DID}#atproto"),
233	            "type": "Multikey",
234	            "controller": WEB_DID,
235	            "publicKeyMultibase": "zRepo"
236	        }]));
237	        assert_eq!(reason(key(&doc)), "no_device_verification_method");
238	    }
