248	        for method in [
249	            json!({"id": format!("{WEB_DID}#device"), "type": "JsonWebKey2020", "controller": WEB_DID, "publicKeyMultibase": "zDevice"}),
250	            json!({"id": format!("{WEB_DID}#device"), "type": "Multikey", "controller": "did:web:attacker.example", "publicKeyMultibase": "zDevice"}),
251	            json!({"id": "did:web:other.example#device", "type": "Multikey", "controller": WEB_DID, "publicKeyMultibase": "zDevice"}),
252	        ] {
253	            assert_eq!(
254	                reason(key(&document(json!([method])))),
255	                "no_device_verification_method"
256	            );
257	        }
258	    }
259	
260	    #[test]
261	    fn a_device_entry_without_a_multibase_key_is_rejected() {
262	        let doc = document(json!([{
263	            "id": format!("{WEB_DID}#device"),
264	            "type": "Multikey",
265	            "controller": WEB_DID
266	        }]));
267	        assert_eq!(reason(key(&doc)), "device_key_not_multibase");
268	    }
269	
270	    #[test]
271	    fn a_document_without_verification_methods_is_rejected() {
272	        assert_eq!(
273	            reason(device_verification_key(&json!({"id": WEB_DID}), WEB_DID)),
274	            "no_verification_methods"
275	        );
276	    }
277	
278	    #[test]
279	    fn plc_did_syntax_is_enforced_exactly() {
280	        assert!(is_plc_did("did:plc:aaaaaaaaaaaaaaaaaaaaaaaa"));
281	        assert!(!is_plc_did("did:plc:tooshort"));
282	        assert!(!is_plc_did("did:plc:AAAAAAAAAAAAAAAAAAAAAAAA"));
283	        assert!(!is_plc_did("did:plc:aaaaaaaaaaaaaaaaaaaaaaa1"));
284	        assert!(!is_plc_did(WEB_DID));
285	    }
286	}
