/// Render the wallet-approval block: a scan QR encoding the `request_id` (+ origin) for the
/// cross-device phone-scan path, the human-typeable `user_code` fallback (no camera / accessibility),
/// an "Open in Obsign" handoff link carrying the same payload for the same-device path, a live status
/// region, and a no-JS "I've approved — continue" form that POSTs to `/oauth/authorize/complete`. An
/// inline script polls `GET /oauth/authorize/status` (backing off on the `slow_down` 429) and, on
/// approval, submits the same completion form — so JS and no-JS reach the identical completion path.
fn render_wallet_path(w: &WalletConsentPath) -> String {
    let request_id = html_escape(w.request_id);
    let user_code = html_escape(w.user_code);
    let handoff = wallet_handoff_uri(w.request_id, w.origin);
    let mut html = String::with_capacity(2048);
    html.push_str("    <div class=\"section-label\">Approve in your wallet</div>\n");
    html.push_str("    <div class=\"wallet\" id=\"wallet-path\" data-request-id=\"");
    html.push_str(&request_id);
    html.push_str("\">\n");
    // Push-delivered prompt (Phase C): the number-match panel leads. The wallet will refuse to
    // approve without this number, so a user whose phone just buzzed reads this block first;
    // everything below stays rendered as the fallback channels for the same request.
    if let Some(match_code) = w.match_code {
        html.push_str(
            "      <p class=\"wallet-lead\">We sent a sign-in request to your wallet. To approve it, enter this number in Obsign:</p>\n",
        );
        html.push_str("      <div class=\"match-code mono\" id=\"match-code\">");
        html.push_str(&html_escape(match_code));
        html.push_str("</div>\n");
        html.push_str(
            "      <p class=\"wallet-lead wallet-or\">No notification? Scan or type the code below instead — you'll still be asked for the number above.</p>\n",
        );
    }
    // Scan path first: the strongest cross-device channel (start from the page, no transcription).
    // Rendered only when the payload actually fits in a QR — otherwise the typed code below stands
    // in, and nothing about the fallback changes.
    if let Some(qr) = render_qr_svg(&handoff) {
        html.push_str(
            "      <p class=\"wallet-lead\">Scan this with Obsign on your phone to approve this sign-in:</p>\n",
        );
        html.push_str("      <div class=\"qr\">");
        html.push_str(&qr);
        html.push_str("</div>\n");
        html.push_str(
            "      <p class=\"wallet-lead wallet-or\">No camera? Open Obsign and enter this code:</p>\n",
        );
    } else {
        html.push_str(
            "      <p class=\"wallet-lead\">Open Obsign and enter this code to approve this sign-in:</p>\n",
        );
    }
    html.push_str("      <div class=\"user-code mono\">");
    html.push_str(&user_code);
    html.push_str("</div>\n");
    html.push_str("      <a class=\"btn btn-approve wallet-open\" href=\"");
    html.push_str(&html_escape(&handoff));
    html.push_str("\">");
    html.push_str(ICON_SEAL_SM);
    html.push_str("Open in Obsign</a>\n");
    html.push_str(
        "      <p class=\"wallet-status\" id=\"wallet-status\" role=\"status\" aria-live=\"polite\">Waiting for approval in your wallet…</p>\n",
    );
    html.push_str(
        "      <form method=\"POST\" action=\"/oauth/authorize/complete\" id=\"complete-form\">\n",
    );
    html.push_str("        <input type=\"hidden\" name=\"request_id\" value=\"");
    html.push_str(&request_id);
    html.push_str("\" />\n");
    html.push_str(
        "        <button type=\"submit\" class=\"btn btn-deny wallet-continue\">I've approved — continue</button>\n",
    );
    html.push_str("      </form>\n");
    html.push_str("    </div>\n");
    html.push_str(WALLET_POLL_SCRIPT);
    html
}

