    prev: null,
    type: 'plc_operation',
    services: {
      atproto_pds: {
        type: 'AtprotoPersonalDataServer',
        endpoint: pdsUrl,
      },
    },
    alsoKnownAs: [`at://${handle}`],
    rotationKeys: [rotationKeyId, recoveryKeyId, repoSigningKeyId],
    verificationMethods: {
      atproto: repoSigningKeyId,
    },
  };

