test('completion is single-use: an approved request mints at most one code', async () => {
  const { requestId } = await startWalletRequest();
  const { response } = await approveWithDeviceKey(fixture.baseUrl, {
    ...signerFor(requestId),
    grantedScope: SCOPE,
  });
