let client: ClientHost;
let metadata: ServerMetadata;
let CLIENT_ID: string;
let REDIRECT_URI: string;

const SCOPE = 'atproto transition:generic';

before(async () => {
  fixture = await startFixture();
  client = await startClientHost();
